From 99c282640be84e2927fc11baf9253a4be00d3d20 Mon Sep 17 00:00:00 2001
From: Yury Popov 
Date: Tue, 8 Nov 2022 23:50:42 +0300
Subject: [PATCH] SSML: Check that skip marker is not empty

---
 src/libespeak-ng/ssml.c | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

diff --git a/src/libespeak-ng/ssml.c b/src/libespeak-ng/ssml.c
index 55bed5231a..8325e355c0 100644
--- a/src/libespeak-ng/ssml.c
+++ b/src/libespeak-ng/ssml.c
@@ -804,7 +804,7 @@ int ProcessSsmlTag(wchar_t *xml_buf, char *outbuf, int *outix, int n_outbuf, con
 			// add name to circular buffer of marker names
 			attrcopy_utf8(buf, attr1, sizeof(buf));

-			if (strcmp(skip_marker, buf) == 0) {
+			if ((buf[0] != 0) && (strcmp(skip_marker, buf) == 0)) {
 				// This is the marker we are waiting for before starting to speak
 				*clear_skipping_text = true;
 				skip_marker[0] = 0;

